/**
 * Game — owns the renderer, the frame loop, the app state machine and race setup/teardown.
 * OWNER: orchestrator. Agents: do NOT edit this file. If you need a hook, expose it from your
 * module and mention it in your final report.
 *
 * Frame order while racing (see ARCHITECTURE.md §5):
 *   input.update → race.update → controllers → items.update → kart.update (physics)
 *   → resolveKartCollisions → race.updateStandings → track.update → kart.model.update
 *   → effects.update → cameraController.update → audio.update → ui.update → postfx.render
 */
import * as THREE from 'three';
import { events } from './core/EventBus.js';
import { EVT } from './core/events.js';
import { CC_CLASSES, DEFAULT_SETTINGS, QUALITY, MODES, GP_POINTS, MAX_KARTS, MAX_PLAYERS, PLAYER_COLORS, DEFAULT_LAPS } from './core/constants.js';
import { makeRng } from './core/math.js';
import { CHARACTERS, getCharacter } from './data/characters.js';
import { createTrack, TRACK_LIST, CUPS } from './track/index.js';
import { InputManager } from './input/InputManager.js';
import { PlayerController } from './input/PlayerController.js';
import { Kart } from './kart/Kart.js';
import { resolveKartCollisions } from './kart/collisions.js';
import { CameraController } from './camera/CameraController.js';
import { KartModel } from './visuals/KartModel.js';
import { Showroom } from './visuals/Showroom.js';
import { Effects } from './fx/Effects.js';
import { PostFX } from './fx/PostFX.js';
import { ItemSystem } from './items/ItemSystem.js';
import { AIController } from './ai/AIController.js';
import { UIManager } from './ui/UIManager.js';
import { AudioManager } from './audio/AudioManager.js';
import { RaceManager } from './race/RaceManager.js';
import { PLATFORM } from './core/platform.js';

const SETTINGS_KEY = 'kartblitz.settings.v1';
const nextFrame = () => new Promise((r) => requestAnimationFrame(() => r()));

export class Game {
  constructor(container) {
    this.container = container;
    this.events = events;
    this.params = new URLSearchParams(location.search);
    this.debug = this._parseDebug(this.params);
    /** Platform flags { mobile, touch, ios, android, standalone } (src/core/platform.js, docs/MOBILE.md). */
    this.platform = PLATFORM;
    /** 'landscape' | 'portrait' — viewport shape. Always 'landscape' off-mobile. Changes emit EVT.ORIENTATION. */
    this.orientation = 'landscape';
    this.settings = this._loadSettings();
    if (this.debug.quality) this.settings.quality = this.debug.quality;

    /** 'boot' | 'menu' | 'loading' | 'race' */
    this.state = 'boot';
    this.paused = false;
    /** Seconds since boot (real time, keeps running while paused). */
    this.time = 0;
    this.frame = 0;
    /** Normalized config of the current/last race (see _normalizeConfig). */
    this.raceConfig = null;
    /** Grand Prix state or null: { cupId, cupName, trackIds, raceIndex, points: {characterId: n}, lastRacePoints } */
    this.gp = null;
    this.track = null;
    /** @type {Kart[]} */
    this.karts = [];
    /** @type {Kart|null} */
    this.player = null;
    /** Human karts in player order ([] outside a race). players[0] === player. */
    this.players = [];
    /** One View per human: { index, kart, camera, cameraController, rect, color } ([] outside a race). */
    this.views = [];
    /** 'single' | 'h2' | 'quad' */
    this.layout = 'single';
    /** 3P only: the free bottom-right quadrant (normalized rect, origin top-left) or null. */
    this.overviewRect = null;
    this.isSplit = false;
    this.trackList = TRACK_LIST;
    this.cups = CUPS;
    this.characters = CHARACTERS;

    // ---- renderer / scene / camera ----
    const r = (this.renderer = new THREE.WebGLRenderer({ antialias: !PLATFORM.mobile, powerPreference: 'high-performance', stencil: false }));
    r.setPixelRatio(this._pixelRatio());
    r.setSize(window.innerWidth, window.innerHeight);
    r.outputColorSpace = THREE.SRGBColorSpace;
    r.toneMapping = THREE.ACESFilmicToneMapping;
    r.toneMappingExposure = 1.0;
    r.shadowMap.enabled = true;
    r.shadowMap.type = THREE.PCFShadowMap;
    r.domElement.id = 'game-canvas';
    container.appendChild(r.domElement);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 5000);
    this.scene.add(this.camera); // allows camera-attached effects

    // ---- systems (all take `game`) ----
    this.input = new InputManager(this);
    this.race = new RaceManager(this);
    this.cameraController = new CameraController(this);
    this.effects = new Effects(this);
    this.items = new ItemSystem(this);
    this.postfx = new PostFX(this);
    this.showroom = new Showroom(this);
    this.audio = new AudioManager(this);
    this.ui = new UIManager(this);
    /** Systems with optional setupRace(ctx)/teardownRace() hooks, called in this order. */
    this._raceSystems = [this.cameraController, this.effects, this.items, this.audio, this.ui];

    // ---- wiring ----
    window.addEventListener('resize', () => this._onResize());
    this._wirePlatform();
    const unlock = () => this.audio.unlock?.();
    window.addEventListener('pointerdown', unlock);
    window.addEventListener('keydown', unlock);
    window.addEventListener('blur', () => {
      if (this.state === 'race' && this.race.isRacing && !this.debug.nopause) this.pause();
    });
    events.on(EVT.RACE_FINISH, ({ kart }) => {
      // CPU takes over the player's kart after the finish line (classic kart-racer behaviour).
      if (kart.isPlayer && kart.controller instanceof PlayerController) {
        kart.controller.dispose?.();
        kart.controller = new AIController(this, kart, { skill: 0.9, autopilot: true });
      }
    });
    if (this.debug.mute) this.audio.setMuted?.(true);

    this._debugEl = null;
    this._fps = { frames: 0, time: 0, value: 0 };
    /** Dynamic resolution: sliding window of real frame times while racing (see _adaptResolution). */
    this._dyn = { t: 0, n: 0, slow: 0, cooldown: 0, lockMs: 0, lockFor: 6000, dropAt: -1e9 };
    /** Last pixel ratio chosen by dynamic resolution on mobile (kept across races so a slow phone doesn't re-learn every race). */
    this._dynLast = null;
    this._contextLost = false;
    this._last = performance.now();
    window.__game = this;
  }

  // =====================================================================================
  // lifecycle
  // =====================================================================================
  start() {
    this._last = performance.now();
    this.renderer.setAnimationLoop((t) => this._frame(t));
    if (this.debug.quick) {
      this.startRace({
        mode: this.debug.mode,
        trackId: this.debug.track,
        characterId: this.debug.char,
        players: this.debug.players,
        cc: this.debug.cc,
        laps: this.debug.laps,
        aiCount: this.debug.ai,
        skipIntro: this.debug.skipIntro,
        noCountdown: this.debug.noCountdown,
      });
    } else {
      this.setState('menu');
    }
  }

  setState(state) {
    const prev = this.state;
    if (prev === state) return;
    this.state = state;
    events.emit(EVT.GAME_STATE, { state, prev });
  }

  _frame(now) {
    const rawMs = now - this._last;
    let dt = rawMs / 1000;
    this._last = now;
    if (this._contextLost) return; // WebGL context is gone (iOS background kill) — wait for webglcontextrestored
    this._adaptResolution(rawMs);
    if (!(dt > 0)) dt = 0;
    dt = Math.min(dt, 1 / 20) * this.debug.timeScale;
    this.time += dt;
    this.frame++;

    this.input.update(dt);
    if (this.state === 'race') this._updateRace(dt);
    else this._updateMenu(dt);
    this._updateDebug(dt);
  }

  _updateMenu(dt) {
    this.showroom.update(dt);
    this.audio.update(dt);
    this.ui.update(dt);
    this.postfx.render(this.showroom.scene, this.showroom.camera, dt);
  }

  _updateRace(dt) {
    const race = this.race;
    if (this.input.pressed('pause') && race.phase !== 'results') this.togglePause();
    const sdt = this.paused ? 0 : dt;

    if (!this.paused) {
      if (race.phase === 'intro' && (this.input.pressed('confirm') || this.input.pressed('item'))) race.skipIntro();
      race.update(sdt);
      for (const k of this.karts) k.controller?.update(sdt);
      this.items.update(sdt);
      for (const k of this.karts) k.update(sdt);
      resolveKartCollisions(this.karts, sdt, this);
      race.updateStandings(sdt);
      this.track?.update(sdt, (this.cameraController.target ?? this.player ?? this.karts[0])?.position ?? null);
      for (const k of this.karts) k.model?.update(sdt, k);
      this.effects.update(sdt);
      const views = this.views;
      if (views.length > 1) for (const v of views) v.cameraController.update(sdt);
      else this.cameraController.update(sdt);
    }
    this.audio.update(dt);
    this.ui.update(dt);
    if (this.views.length > 1 && this.postfx.renderViews) this.postfx.renderViews(this.scene, this.views, sdt);
    else this.postfx.render(this.scene, this.camera, sdt);
  }

  // =====================================================================================
  // race management API (used by UI)
  // =====================================================================================
  /**
   * Start a race. cfg: { mode: 'gp'|'quick'|'timetrial', characterId, trackId?, cupId?, cc?, laps?, aiCount? }
   * For mode 'gp' pass cupId (trackId is taken from the cup); a new GP starts unless cfg._continueGp.
   */
  async startRace(cfg = {}) {
    if (this._loadingRace) return;
    this._loadingRace = true;
    try {
      const config = this._normalizeConfig(cfg);
      if (config.mode === 'gp' && !cfg._continueGp) {
        const cup = CUPS.find((c) => c.id === config.cupId) ?? CUPS[0];
        this.gp = { cupId: cup.id, cupName: cup.name, trackIds: [...cup.trackIds], raceIndex: 0, points: {}, lastRacePoints: null };
        config.trackId = this.gp.trackIds[0];
      } else if (config.mode !== 'gp') {
        this.gp = null;
      }
      this.raceConfig = config;
      this._clearPause();
      this.setState('loading');
      await nextFrame();
      await nextFrame();

      this._teardownRace();
      const wantPr = this._startPixelRatio();
      if (this.renderer.getPixelRatio() !== wantPr) {
        this.renderer.setPixelRatio(wantPr);
        this._onResize();
      }
      this._dyn.t = this._dyn.n = this._dyn.slow = 0;
      this._dyn.cooldown = 3000; // ignore shader-warmup frames at the start of a race
      this.track = createTrack(config.trackId, this);
      this.track.build();
      this._spawnKarts(config);
      this._buildViews(config);

      const ctx = { track: this.track, karts: this.karts, player: this.player, players: this.players, views: this.views, config };
      for (const sys of this._raceSystems) sys.setupRace?.(ctx);
      // extra views' camera controllers are not in _raceSystems
      for (const v of this.views) if (v.cameraController !== this.cameraController) v.cameraController.setupRace?.({ ...ctx, player: v.kart });
      events.emit(EVT.VIEWS_CHANGED, { views: this.views, layout: this.layout, overviewRect: this.overviewRect });
      events.emit(EVT.RACE_SETUP, ctx);
      this.race.setup(ctx);
      try {
        this.renderer.compile(this.scene, this.camera);
      } catch (e) {
        console.warn('[Game] shader precompile failed', e);
      }
      this.setState('race');
    } catch (err) {
      console.error('[Game] startRace failed:', err);
      this.setState('menu');
    } finally {
      this._loadingRace = false;
    }
  }

  /** Restart the current race with the same config. In a GP, points from a completed attempt are reverted. */
  restartRace() {
    if (!this.raceConfig) return;
    if (this.gp && this.gp.lastRacePoints && this.race.phase === 'results') {
      for (const [id, pts] of Object.entries(this.gp.lastRacePoints)) this.gp.points[id] = (this.gp.points[id] ?? 0) - pts;
      this.gp.lastRacePoints = null;
    }
    this.startRace({ ...this.raceConfig, _continueGp: !!this.gp });
  }

  /** GP: advance to the next track, or finish the cup (emits GP_COMPLETE and returns to menu). */
  nextRace() {
    if (!this.gp) return this.quitToMenu();
    if (this.gp.raceIndex < this.gp.trackIds.length - 1) {
      this.gp.raceIndex++;
      this.gp.lastRacePoints = null;
      this.startRace({ ...this.raceConfig, trackId: this.gp.trackIds[this.gp.raceIndex], _continueGp: true });
    } else {
      const standings = this.getGpStandings();
      this._teardownRace();
      this._clearPause();
      this.setState('menu');
      events.emit(EVT.GP_COMPLETE, { standings, cupName: this.gp.cupName });
    }
  }

  get isLastGpRace() {
    return !!this.gp && this.gp.raceIndex >= this.gp.trackIds.length - 1;
  }

  /** [{ characterId, name, points, isPlayer, playerIndex }] sorted by points desc (humans first on ties). */
  getGpStandings() {
    if (!this.gp) return [];
    const humans = new Map((this.raceConfig?.players ?? []).map((p) => [p.characterId, p.index]));
    const ids = new Set([...Object.keys(this.gp.points), ...(this.karts.map((k) => k.character.id))]);
    return [...ids]
      .map((id) => ({
        characterId: id,
        name: getCharacter(id).name,
        points: this.gp.points[id] ?? 0,
        isPlayer: humans.has(id),
        playerIndex: humans.has(id) ? humans.get(id) : -1,
      }))
      .sort((a, b) => b.points - a.points || (a.isPlayer === b.isPlayer ? a.playerIndex - b.playerIndex : a.isPlayer ? -1 : 1));
  }

  quitToMenu() {
    this._teardownRace();
    this.gp = null;
    this._clearPause();
    this.setState('menu');
  }

  pause() {
    if (this.state !== 'race' || this.paused) return;
    this.paused = true;
    events.emit(EVT.GAME_PAUSE, { paused: true });
  }
  resume() {
    if (!this.paused) return;
    this.paused = false;
    this._last = performance.now();
    events.emit(EVT.GAME_PAUSE, { paused: false });
  }
  togglePause() {
    this.paused ? this.resume() : this.pause();
  }

  /** Leave the paused state (emitting GAME_PAUSE so UI/audio restore themselves) without resuming a race. */
  _clearPause() {
    if (!this.paused) return;
    this.paused = false;
    this._last = performance.now();
    events.emit(EVT.GAME_PAUSE, { paused: false });
  }

  /** Persisted settings. Emits SETTINGS_CHANGED. Keys: see DEFAULT_SETTINGS. */
  setSetting(key, value) {
    this.settings[key] = value;
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(this.settings));
    } catch {}
    if (key === 'quality') {
      this._dynLast = null;
      this.settings._qualityPicked = true; // an explicit user choice: don't override it with the platform default
      try {
        localStorage.setItem(SETTINGS_KEY, JSON.stringify(this.settings));
      } catch {}
      this.renderer.setPixelRatio(this._pixelRatio());
      this.postfx.setQuality?.(value);
      this._onResize();
    }
    events.emit(EVT.SETTINGS_CHANGED, { settings: this.settings, key });
  }

  /** Called by RaceManager right before RACE_RESULTS is emitted. */
  _applyGpPoints(results) {
    if (!this.gp || this.raceConfig?.mode !== 'gp') return;
    const awarded = {};
    for (const r of results) {
      const pts = GP_POINTS[r.place - 1] ?? 0;
      r.points = pts;
      awarded[r.characterId] = pts;
      this.gp.points[r.characterId] = (this.gp.points[r.characterId] ?? 0) + pts;
      r.totalPoints = this.gp.points[r.characterId];
    }
    this.gp.lastRacePoints = awarded;
  }

  // =====================================================================================
  // internals
  // =====================================================================================
  _normalizeConfig(cfg) {
    const mode = MODES[cfg.mode] ? cfg.mode : 'quick';
    const trackIds = TRACK_LIST.map((t) => t.id);
    const trackId = trackIds.includes(cfg.trackId) ? cfg.trackId : trackIds[0];
    const cc = CC_CLASSES[cfg.cc] ? Number(cfg.cc) : this.settings.cc;
    // ---- players: 1..MAX_PLAYERS humans, distinct characters ----
    let reqPlayers = Array.isArray(cfg.players) && cfg.players.length ? cfg.players : [{ characterId: cfg.characterId, device: 'any' }];
    reqPlayers = reqPlayers.slice(0, mode === 'timetrial' || PLATFORM.mobile ? 1 : MAX_PLAYERS);
    if (PLATFORM.mobile) reqPlayers = [{ characterId: reqPlayers[0]?.characterId ?? cfg.characterId, device: 'any' }]; // phones: single player, touch/any input
    const used = new Set();
    const players = reqPlayers.map((p, i) => {
      let ch = getCharacter(p?.characterId);
      if (used.has(ch.id)) ch = CHARACTERS.find((c) => !used.has(c.id)) ?? ch;
      used.add(ch.id);
      return { index: i, characterId: ch.id, device: typeof p?.device === 'string' && p.device ? p.device : 'any' };
    });
    const characterId = players[0].characterId;
    const maxAi = MAX_KARTS - players.length;
    const aiCount = MODES[mode].ai ? (Number.isFinite(cfg.aiCount) ? Math.max(0, Math.min(maxAi, cfg.aiCount)) : maxAi) : 0;
    return {
      players,
      mode,
      trackId,
      cupId: cfg.cupId ?? CUPS[0]?.id,
      characterId,
      cc,
      ccClass: CC_CLASSES[cc],
      laps: Number.isFinite(cfg.laps) && cfg.laps > 0 ? cfg.laps : DEFAULT_LAPS,
      aiCount,
      items: MODES[mode].items,
      skipIntro: !!cfg.skipIntro,
      noCountdown: !!cfg.noCountdown,
    };
  }

  _spawnKarts(config) {
    const humanChars = config.players.map((p) => getCharacter(p.characterId));
    const humanIds = new Set(humanChars.map((c) => c.id));
    const others = CHARACTERS.filter((c) => !humanIds.has(c.id)).slice(0, config.aiCount);
    // Grid order (slot 0 = pole): first race → humans start last (P1 last); later GP races → by GP standings.
    let roster = [...others, ...[...humanChars].reverse()];
    if (this.gp && this.gp.raceIndex > 0) {
      const pts = this.gp.points;
      roster.sort((a, b) => (pts[b.id] ?? 0) - (pts[a.id] ?? 0));
    }
    const rng = makeRng(1337 + (this.gp?.raceIndex ?? 0));
    const baseSkill = config.ccClass.aiSkill;
    // two "rival" CPUs are sharper than the rest
    const rivalIds = new Set(others.slice(0, 2).map((c) => c.id));
    const grid = this.track.startGrid;
    const playerCount = config.players.length;

    roster.forEach((character, slot) => {
      const pi = humanChars.findIndex((c) => c.id === character.id);
      const isPlayer = pi >= 0;
      const kart = new Kart(this, { id: slot, character, isPlayer });
      kart.playerIndex = isPlayer ? pi : -1;
      kart.model = new KartModel(character, { isPlayer, quality: this.settings.quality, playerIndex: kart.playerIndex, playerCount });
      this.scene.add(kart.model.root);
      kart.resetForRace(grid[Math.min(slot, grid.length - 1)]);
      kart.controlLocked = true;
      if (isPlayer && !this.debug.autodrive) {
        const device = config.players[pi].device;
        kart.controller = new PlayerController(this, kart, this.input.getSource?.(device) ?? this.input);
      } else {
        const skill = isPlayer ? 0.9 : Math.max(0.05, Math.min(1, baseSkill + (rivalIds.has(character.id) ? 0.08 : -0.04 - rng() * 0.12)));
        kart.controller = new AIController(this, kart, { skill, autopilot: isPlayer });
      }
      this.karts.push(kart);
    });
    this.players = humanChars.map((c) => this.karts.find((k) => k.character.id === c.id));
    this.player = this.players[0] ?? null;
  }

  /** Normalized viewport rects (origin top-left) for a layout. */
  static layoutRects(n) {
    if (n <= 1) return { layout: 'single', rects: [{ x: 0, y: 0, w: 1, h: 1 }], overview: null };
    if (n === 2) return { layout: 'h2', rects: [{ x: 0, y: 0, w: 1, h: 0.5 }, { x: 0, y: 0.5, w: 1, h: 0.5 }], overview: null };
    const q = [{ x: 0, y: 0, w: 0.5, h: 0.5 }, { x: 0.5, y: 0, w: 0.5, h: 0.5 }, { x: 0, y: 0.5, w: 0.5, h: 0.5 }, { x: 0.5, y: 0.5, w: 0.5, h: 0.5 }];
    return { layout: 'quad', rects: q.slice(0, n), overview: n === 3 ? { ...q[3] } : null };
  }

  /** Build one View (camera + CameraController + rect) per human. views[0] reuses game.camera/cameraController. */
  _buildViews(config) {
    const { layout, rects, overview } = Game.layoutRects(this.players.length);
    this.layout = layout;
    this.overviewRect = overview;
    this.views = this.players.map((kart, i) => {
      let camera = this.camera;
      let cameraController = this.cameraController;
      if (i > 0) {
        camera = new THREE.PerspectiveCamera(70, 1, 0.1, 5000);
        this.scene.add(camera);
        cameraController = new CameraController(this, { camera });
        if (cameraController.camera !== camera) cameraController.camera = camera; // pre-`{ camera }` fallback
      }
      return { index: i, kart, camera, cameraController, rect: rects[i], color: PLAYER_COLORS[i] };
    });
    this.isSplit = this.views.length > 1;
    this._updateViewAspects();
  }

  _updateViewAspects() {
    const W = window.innerWidth, H = window.innerHeight;
    for (const v of this.views) {
      v.camera.aspect = (v.rect.w * W) / Math.max(1, v.rect.h * H);
      v.camera.updateProjectionMatrix();
    }
  }

  _teardownRace() {
    if (!this.track && this.karts.length === 0) return;
    events.emit(EVT.RACE_TEARDOWN, {});
    const hadViews = this.views.length > 0;
    for (const v of this.views) {
      if (v.cameraController === this.cameraController) continue;
      try {
        v.cameraController.teardownRace?.();
        v.cameraController.dispose?.();
      } catch (e) {
        console.error('[Game] extra camera teardown failed', e);
      }
      this.scene.remove(v.camera);
    }
    this.views = [];
    this.players = [];
    this.layout = 'single';
    this.overviewRect = null;
    this.isSplit = false;
    if (hadViews) events.emit(EVT.VIEWS_CHANGED, { views: [], layout: 'single', overviewRect: null });
    for (const sys of this._raceSystems) {
      try {
        sys.teardownRace?.();
      } catch (e) {
        console.error('[Game] teardownRace failed for', sys?.constructor?.name, e);
      }
    }
    for (const k of this.karts) {
      k.controller?.dispose?.();
      if (k.model) {
        this.scene.remove(k.model.root);
        k.model.dispose?.();
      }
      k.dispose?.();
    }
    this.karts = [];
    this.player = null;
    this.track?.dispose();
    this.track = null;
    this.race.reset();
  }

  _pixelRatio() {
    const q = QUALITY[this.settings.quality] ?? QUALITY.high;
    return Math.min(window.devicePixelRatio || 1, q.pixelRatio);
  }

  /** Pixel ratio for a new race: the preset cap, or (mobile) the last dynamic-resolution level if it dropped lower. */
  _startPixelRatio() {
    const cap = this._pixelRatio();
    return PLATFORM.mobile && this._dynLast ? Math.min(cap, this._dynLast) : cap;
  }

  /** Internal render resolution relative to CSS pixels (renderer pixel ratio) — read-only, for debugging dynamic resolution. */
  get renderScale() {
    return this.renderer.getPixelRatio();
  }

  /**
   * Dynamic resolution scaling. While racing, if most frames over a 2 s window miss ~50 fps, drop the render
   * pixel ratio by 0.25 (never below 1 on desktop; down to 0.75 in steps of 0.125 on mobile); if frames are
   * consistently fast, climb back toward the quality preset's cap (mobile: only after a growing lockout following
   * each drop, so a phone that can't hold 60 fps doesn't oscillate). Hitches (> 250 ms, tab switches) and pauses
   * are ignored.
   */
  _adaptResolution(rawMs) {
    const d = this._dyn;
    if (this.state !== 'race' || this.paused || !(rawMs > 0) || rawMs > 250 || this.debug.timeScale !== 1) return;
    if (d.cooldown > 0) {
      d.cooldown -= rawMs;
      return;
    }
    d.t += rawMs;
    d.n++;
    const mob = PLATFORM.mobile;
    if (rawMs > (mob ? 21 : 20.5)) d.slow++;
    if (d.lockMs > 0) d.lockMs -= rawMs;
    if (d.t < 2000) return;
    const slowFrac = d.slow / d.n;
    const avg = d.t / d.n;
    d.t = d.n = d.slow = 0;
    const cap = this._pixelRatio();
    const cur = this.renderer.getPixelRatio();
    const floor = mob ? 0.75 : 1;
    const step = mob ? 0.125 : 0.25;
    let next = cur;
    if (slowFrac > (mob ? 0.4 : 0.6) && cur > floor) {
      next = Math.max(floor, cur - step);
      if (mob) {
        // dropped again soon after climbing → back off the climbing for longer
        d.lockFor = performance.now() - d.dropAt < 20000 ? Math.min(60000, d.lockFor * 2) : 6000;
        d.lockMs = d.lockFor;
        d.dropAt = performance.now();
      }
    } else if (cur < cap && (mob ? slowFrac < 0.02 && avg < 18 && d.lockMs <= 0 : avg < 12.5)) {
      next = Math.min(cap, cur + step);
    }
    if (next !== cur) {
      this.renderer.setPixelRatio(next);
      if (mob) this._dynLast = next;
      this._onResize();
      d.cooldown = 1500; // let the new resolution settle before measuring again
      console.info(`[Game] dynamic resolution: pixel ratio ${cur} → ${next} (avg ${avg.toFixed(1)} ms, ${(slowFrac * 100) | 0}% slow frames)`);
    }
  }

  _onResize() {
    const w = window.innerWidth, h = window.innerHeight;
    this.renderer.setSize(w, h);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    if (this.views.length) this._updateViewAspects();
    this.postfx.setSize?.(w, h);
    this.showroom.resize?.(w, h);
    this._updateOrientation();
  }

  // =====================================================================================
  // platform (mobile) plumbing — see docs/MOBILE.md §3.1
  // =====================================================================================
  _wirePlatform() {
    const canvas = this.renderer.domElement;
    // visibility: backgrounding the tab/app pauses a running race (in addition to window blur)
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'race' && this.race.isRacing && !this.debug.nopause) this.pause();
      if (!document.hidden) this._last = performance.now();
    });
    // WebGL context loss (iOS kills contexts of backgrounded pages)
    canvas.addEventListener('webglcontextlost', (e) => {
      e.preventDefault();
      this._contextLost = true;
      console.warn('[Game] WebGL context lost');
      if (this.state === 'race' && !this.paused) this.pause();
    });
    canvas.addEventListener('webglcontextrestored', () => this._onContextRestored());
    if (!PLATFORM.mobile) return;
    // viewport: iOS toolbar show/hide, rotation (iOS reports stale sizes right after orientationchange → re-measure)
    const resize = () => this._onResize();
    window.visualViewport?.addEventListener('resize', resize);
    window.addEventListener('orientationchange', () => {
      resize();
      setTimeout(resize, 120);
      setTimeout(resize, 400);
    });
    screen.orientation?.addEventListener?.('change', resize);
    // no pinch / double-tap zoom, no context menu on long-press
    for (const t of ['gesturestart', 'gesturechange', 'gestureend']) document.addEventListener(t, (e) => e.preventDefault());
    document.addEventListener('contextmenu', (e) => e.preventDefault());
    document.addEventListener('dblclick', (e) => e.preventDefault());
    document.addEventListener('touchmove', (e) => { if (e.touches.length > 1) e.preventDefault(); }, { passive: false });
    this._updateOrientation();
  }

  /** Recompute `game.orientation`; on change emit EVT.ORIENTATION and (mobile) auto-pause a running race in portrait. */
  _updateOrientation() {
    const o = PLATFORM.mobile && window.innerHeight > window.innerWidth ? 'portrait' : 'landscape';
    if (o === this.orientation) return;
    this.orientation = o;
    if (o === 'portrait' && this.state === 'race' && this.race.phase !== 'results' && !this.paused && !this.debug.nopause) this.pause();
    events.emit(EVT.ORIENTATION, { orientation: o });
  }

  /**
   * Enter fullscreen + lock landscape where supported (Android Chrome, iPadOS). Call from a user gesture (first tap on
   * the title). Safe no-op on desktop, in an installed PWA, and on iPhone Safari (which has neither API).
   * @returns {Promise<boolean>} whether fullscreen is active afterwards
   */
  async requestFullscreen() {
    if (!PLATFORM.mobile || PLATFORM.standalone) return false;
    const el = document.documentElement;
    const req = el.requestFullscreen || el.webkitRequestFullscreen;
    if (req && !(document.fullscreenElement || document.webkitFullscreenElement)) {
      try {
        await req.call(el, { navigationUI: 'hide' });
      } catch {}
    }
    try {
      await screen.orientation?.lock?.('landscape');
    } catch {}
    return !!(document.fullscreenElement || document.webkitFullscreenElement);
  }

  /** WebGL context came back. three.js re-initialises its GL state lazily; we restart the race (fresh GPU resources) or just resume the menu. */
  _onContextRestored() {
    console.warn('[Game] WebGL context restored');
    this._contextLost = false;
    this._last = performance.now();
    this._onResize();
    const action = this.state === 'race' || this.state === 'loading' ? 'restart' : 'menu';
    if (action === 'restart' && !this._loadingRace && this.raceConfig) {
      this._clearPause();
      this.restartRace();
    }
    events.emit(EVT.CONTEXT_RESTORED, { action });
  }

  _loadSettings() {
    let saved = {};
    try {
      saved = JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}');
    } catch {}
    const s = { ...DEFAULT_SETTINGS, ...saved };
    if (!QUALITY[s.quality]) s.quality = DEFAULT_SETTINGS.quality;
    // Platform default quality unless the user picked one explicitly on this device: phones start on 'mobile',
    // and a stray 'mobile' (saved while testing with ?mobile=1) never sticks on desktop.
    if (!saved._qualityPicked || (!PLATFORM.mobile && s.quality === 'mobile')) {
      if (PLATFORM.mobile) s.quality = 'mobile';
      else if (s.quality === 'mobile') s.quality = DEFAULT_SETTINGS.quality;
    }
    return s;
  }

  _parseDebug(p) {
    const num = (k, d) => (p.has(k) && Number.isFinite(Number(p.get(k))) ? Number(p.get(k)) : d);
    const flag = (k) => p.has(k) && p.get(k) !== '0' && p.get(k) !== 'false';
    return {
      quick: flag('quick'),
      mode: p.get('mode') || 'quick',
      track: p.get('track') || undefined,
      char: p.get('char') || undefined,
      cc: num('cc', undefined),
      laps: num('laps', undefined),
      ai: num('ai', undefined),
      players: PLATFORM.mobile ? undefined : this._parsePlayersParam(p), // phones are single player
      autodrive: flag('autodrive'),
      skipIntro: flag('skipintro'),
      noCountdown: flag('nocountdown'),
      debug: flag('debug'),
      mute: flag('mute'),
      nopause: flag('nopause'),
      quality: ['low', 'medium', 'high', 'mobile'].includes(p.get('quality')) ? p.get('quality') : undefined,
      timeScale: Math.max(0.05, Math.min(8, num('timescale', 1))),
    };
  }

  /** URL: players=1..4, pchars=a,b,.., pdev=kb1,kb2,.. → [{ characterId, device }] or undefined (only meaningful with quick=1). */
  _parsePlayersParam(p) {
    const n = Math.max(1, Math.min(MAX_PLAYERS, Math.floor(Number(p.get('players')) || 1)));
    if (n <= 1 && !p.has('pdev') && !p.has('pchars')) return undefined;
    const chars = (p.get('pchars') || p.get('char') || '').split(',').filter(Boolean);
    const devs = (p.get('pdev') || '').split(',').filter(Boolean);
    const defDev = ['kb1', 'kb2', 'pad0', 'pad1'];
    const used = new Set(chars);
    const free = CHARACTERS.map((c) => c.id).filter((id) => !used.has(id));
    return Array.from({ length: n }, (_, i) => ({
      characterId: chars[i] ?? free.shift() ?? CHARACTERS[i].id,
      device: devs[i] ?? (n > 1 ? defDev[i] : 'any'),
    }));
  }

  _updateDebug(dt) {
    const f = this._fps;
    f.frames++;
    f.time += dt / this.debug.timeScale;
    if (f.time >= 0.5) {
      f.value = f.frames / f.time;
      f.frames = 0;
      f.time = 0;
      if (this.debug.debug || this.settings.showFps) {
        if (!this._debugEl) {
          this._debugEl = document.createElement('div');
          this._debugEl.style.cssText =
            'position:fixed;right:8px;bottom:8px;z-index:99999;font:12px/1.35 ui-monospace,Menlo,monospace;color:#0f0;background:rgba(0,0,0,.6);padding:6px 8px;border-radius:6px;pointer-events:none;white-space:pre';
          document.body.appendChild(this._debugEl);
        }
        const info = this.renderer.info.render;
        let txt = `${f.value.toFixed(0)} fps`;
        if (this.debug.debug) {
          txt += `  calls ${info.calls}  tris ${(info.triangles / 1000).toFixed(0)}k\nstate ${this.state}  phase ${this.race.phase}`;
          const p = this.player;
          if (p) {
            txt += `\nspd ${p.speed.toFixed(1)}  lap ${p.lap}  place ${p.place}  s ${p.trackS?.toFixed(0)}  lat ${p.lateral?.toFixed(1)}  ${p.surface}`;
            txt += `\ndrift ${p.driftLevel}  boost ${p.boostTime.toFixed(2)}  item ${p.item ?? '-'}x${p.itemCount}`;
          }
        }
        this._debugEl.textContent = txt;
      } else if (this._debugEl) {
        this._debugEl.remove();
        this._debugEl = null;
      }
    }
  }
}
